  [inst : Field.{u_1} k] [inst_1 : Ring.{u_2} A] [inst_2 : Algebra.{u_1, u_2} k A] [inst_3 : Ring.{u_3} B]
  [inst_4 : Algebra.{u_1, u_3} k B] [inst_5 : AddCommGroup.{u_4} V] [inst_6 : Module.{u_1, u_4} k V]
  [inst_7 : Module.{u_2, u_4} A V] [inst_8 : IsScalarTower.{u_1, u_2, u_4} k A V] [FiniteDimensional.{u_1, u_4} k V]
  [inst_10 : AddCommGroup.{u_5} W] [inst_11 : Module.{u_1, u_5} k W] [inst_12 : Module.{u_3, u_5} B W]
  [inst_13 : IsScalarTower.{u_1, u_3, u_5} k B W] [FiniteDimensional.{u_1, u_5} k W] [inst_15 : AddCommGroup.{u_6} V']
  [inst_16 : Module.{u_1, u_6} k V'] [inst_17 : Module.{u_2, u_6} A V'] [inst_18 : IsScalarTower.{u_1, u_2, u_6} k A V']
  [FiniteDimensional.{u_1, u_6} k V'] [inst_20 : AddCommGroup.{u_7} W'] [inst_21 : Module.{u_1, u_7} k W']
  [inst_22 : Module.{u_3, u_7} B W'] [inst_23 : IsScalarTower.{u_1, u_3, u_7} k B W']
  [FiniteDimensional.{u_1, u_7} k W'] [IsSimpleModule.{u_2, u_4} A V] [IsSimpleModule.{u_2, u_6} A V']
  [IsSimpleModule.{u_3, u_5} B W] [IsSimpleModule.{u_3, u_7} B W']
  (e :
    LinearEquiv.{u_1, u_1, max u_5 u_4, max u_7 u_6} (RingHom.id.{u_1} k) (TensorProduct.{u_1, u_4, u_5} k V W)
      (TensorProduct.{u_1, u_6, u_7} k V' W')),
  (∀ (a : A) (x : TensorProduct.{u_1, u_4, u_5} k V W),
      Eq.{max (u_6 + 1) (u_7 + 1)}
        (DFunLike.coe.{max (max (max (u_4 + 1) (u_5 + 1)) (u_6 + 1)) (u_7 + 1), max (u_4 + 1) (u_5 + 1),
            max (u_6 + 1) (u_7 + 1)}
          e
          (DFunLike.coe.{max (u_4 + 1) (u_5 + 1), max (u_4 + 1) (u_5 + 1), max (u_4 + 1) (u_5 + 1)}
            (TensorProduct.map.{u_1, u_1, u_4, u_5, u_4, u_5}
              (DFunLike.coe.{max (u_2 + 1) (u_4 + 1), u_2 + 1, u_4 + 1} (Algebra.lsmul.{u_1, u_2, u_1, u_4} k k V) a)
              LinearMap.id.{u_1, u_5})
            x))
        (DFunLike.coe.{max (u_6 + 1) (u_7 + 1), max (u_6 + 1) (u_7 + 1), max (u_6 + 1) (u_7 + 1)}
          (TensorProduct.map.{u_1, u_1, u_6, u_7, u_6, u_7}
            (DFunLike.coe.{max (u_2 + 1) (u_6 + 1), u_2 + 1, u_6 + 1} (Algebra.lsmul.{u_1, u_2, u_1, u_6} k k V') a)
            LinearMap.id.{u_1, u_7})
          (DFunLike.coe.{max (max (max (u_4 + 1) (u_5 + 1)) (u_6 + 1)) (u_7 + 1), max (u_4 + 1) (u_5 + 1),
              max (u_6 + 1) (u_7 + 1)}
            e x))) →
    (∀ (b : B) (x : TensorProduct.{u_1, u_4, u_5} k V W),
        Eq.{max (u_6 + 1) (u_7 + 1)}
          (DFunLike.coe.{max (max (max (u_4 + 1) (u_5 + 1)) (u_6 + 1)) (u_7 + 1), max (u_4 + 1) (u_5 + 1),
              max (u_6 + 1) (u_7 + 1)}
            e
            (DFunLike.coe.{max (u_5 + 1) (u_4 + 1), max (u_5 + 1) (u_4 + 1), max (u_5 + 1) (u_4 + 1)}
              (TensorProduct.map.{u_1, u_1, u_4, u_5, u_4, u_5} LinearMap.id.{u_1, u_4}
                (DFunLike.coe.{max (u_3 + 1) (u_5 + 1), u_3 + 1, u_5 + 1} (Algebra.lsmul.{u_1, u_3, u_1, u_5} k k W) b))
              x))
          (DFunLike.coe.{max (u_7 + 1) (u_6 + 1), max (u_7 + 1) (u_6 + 1), max (u_7 + 1) (u_6 + 1)}
            (TensorProduct.map.{u_1, u_1, u_6, u_7, u_6, u_7} LinearMap.id.{u_1, u_6}
              (DFunLike.coe.{max (u_3 + 1) (u_7 + 1), u_3 + 1, u_7 + 1} (Algebra.lsmul.{u_1, u_3, u_1, u_7} k k W') b))
            (DFunLike.coe.{max (max (max (u_4 + 1) (u_5 + 1)) (u_6 + 1)) (u_7 + 1), max (u_4 + 1) (u_5 + 1),
                max (u_6 + 1) (u_7 + 1)}
              e x))) →
      And (Nonempty.{max (u_6 + 1) (u_4 + 1)} (LinearEquiv.{u_2, u_2, u_4, u_6} (RingHom.id.{u_2} A) V V'))
        (Nonempty.{max (u_7 + 1) (u_5 + 1)} (LinearEquiv.{u_3, u_3, u_5, u_7} (RingHom.id.{u_3} B) W W'))
